fn all_characters_same(s: &[u8]) -> bool {
    // An empty array or a single-element array is considered to have all identical characters
    if s.is_empty() || s.len() == 1 {
        return true;
    }

    // Get the first character to compare against
    let first_char = s[0];

    // Iterate through the array starting from the second element
    for &byte in &s[1..] {
        if byte != first_char {
            return false; // Found a different character
        }
    }

    true // All characters are the same
}